result:
```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;

  return function (...args) {
    const now = Date.now();
    const remaining = wait - (now - last);

    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = now;
      fn.apply(this, args);
    } else if (!timer) {
      // Trailing call so the final scroll position isn't missed
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

const onScroll = throttle(() => {
  console.log('scrollY:', window.scrollY);
}, 200);

window.addEventListener('scroll', onScroll, { passive: true });
```

The handler fires immediately on the first scroll event, then at most once per 200 ms while scrolling continues. The trailing timer guarantees one last call after scrolling stops, so you always act on the final scroll position.

`{ passive: true }` tells the browser the handler won't call `preventDefault()`, which keeps scrolling smooth.

To remove it later, pass the same reference: `window.removeEventListener('scroll', onScroll)`.

```js
try {
  const res = await fetch(url, { signal: AbortSignal.timeout(5000) });
  const data = await res.json();
} catch (err) {
  if (err.name === 'TimeoutError') {
    console.error('Request timed out after 5 s');
  } else {
    throw err;
  }
}
```

`AbortSignal.timeout(5000)` aborts the request after 5 seconds and rejects with a `TimeoutError`. The timeout covers the whole request, including reading the body, so a stalled `res.json()` is also cut off. It is supported in all current browsers and Node 17.3+.

If you also need to cancel manually (say, on component unmount), combine signals:

```js
const controller = new AbortController();

const res = await fetch(url, {
  signal: AbortSignal.any([controller.signal, AbortSignal.timeout(5000)]),
});

// elsewhere: controller.abort();
```

For older environments without `AbortSignal.timeout`, do it by hand:

```js
const controller = new AbortController();
const timer = setTimeout(() => controller.abort(), 5000);

try {
  const res = await fetch(url, { signal: controller.signal });
  const data = await res.json();
} finally {
  clearTimeout(timer);
}
```

Here the rejection is an `AbortError` rather than a `TimeoutError`.

```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

// Postgres error codes for a malformed timestamp or id in the cursor
const BAD_CURSOR_CODES = new Set(['22007', '22008', '22P02']);

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_ts, String(row.id)])).toString('base64url');
}

function decodeCursor(cursor) {
  if (typeof cursor !== 'string') return null;
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
    if (typeof ts !== 'string' || typeof id !== 'string') return null;
    return { ts, id };
  } catch {
    return null;
  }
}

router.get('/orders', async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1) {
    return res.status(400).json({ error: 'limit must be a positive integer' });
  }
  const pageSize = Math.min(limit, MAX_LIMIT);

  let cursor = null;
  if (req.query.cursor !== undefined) {
    cursor = decodeCursor(req.query.cursor);
    if (!cursor) return res.status(400).json({ error: 'invalid cursor' });
  }

  // Fetch one extra row to learn whether another page exists
  const params = [pageSize + 1];
  let where = '';
  if (cursor) {
    params.push(cursor.ts, cursor.id);
    where = 'WHERE (created_at, id) < ($2::timestamptz, $3)';
  }

  try {
    const { rows } = await pool.query(
      `SELECT id, customer_id, status, total, created_at,
              created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params
    );

    const hasMore = rows.length > pageSize;
    const page = hasMore ? rows.slice(0, pageSize) : rows;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      nextCursor: hasMore ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    if (BAD_CURSOR_CODES.has(err.code)) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;
```

The client calls `GET /orders?limit=20`, then passes the returned `nextCursor` back as `GET /orders?limit=20&cursor=...` until `nextCursor` is `null`. Orders come back newest first. I have not run this code, and the column list (`customer_id`, `status`, `total`) is a guess at your schema.

It needs a matching index so each page is an index range scan instead of a sort:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

- **Row comparison:** `(created_at, id) < ($2, $3)` breaks ties between orders with the same `created_at` by `id`, so no rows are skipped or repeated across pages.
- **Timestamp precision:** the cursor carries `created_at::text` rather than the JavaScript `Date`, because `Date` drops Postgres's microseconds and would skip or repeat rows at page boundaries.
- **Column type:** the cast assumes `created_at` is `timestamptz`; if it is `timestamp` without time zone, change the cast to `::timestamp`.
- **Limit:** values above 100 are clamped to 100 rather than rejected.
- **Cursor trust:** the cursor is only base64-encoded, so clients can read and forge it. That is harmless here because it only selects a position, but if you add per-user filtering, keep that in the `WHERE` clause and not in the cursor.

```go
package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, short, usage string
	isBool             bool
	boolVal            *bool
	strVal             *string
	def                string
}

type Parser struct {
	name        string
	positionals string // shown in the usage line, e.g. "<file>..."
	flags       []*flagDef
	lookup      map[string]*flagDef
	args        []string
}

func NewParser(name, positionals string) *Parser {
	return &Parser{name: name, positionals: positionals, lookup: map[string]*flagDef{}}
}

func (p *Parser) add(f *flagDef) {
	p.flags = append(p.flags, f)
	p.lookup[f.name] = f
	if f.short != "" {
		p.lookup[f.short] = f
	}
}

// Bool defines a boolean flag. Pass "" for short to omit the short form.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.add(&flagDef{name: name, short: short, usage: usage, isBool: true, boolVal: v})
	return v
}

// String defines a flag that takes a value.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	p.add(&flagDef{name: name, short: short, usage: usage, strVal: v, def: def})
	return v
}

// Args returns the positional arguments left after Parse.
func (p *Parser) Args() []string { return p.args }

func (p *Parser) Parse(argv []string) error {
	p.args = nil
	for i := 0; i < len(argv); i++ {
		arg := argv[i]
		if arg == "--" {
			p.args = append(p.args, argv[i+1:]...)
			break
		}
		// A lone "-" is positional (conventionally stdin).
		if len(arg) < 2 || arg[0] != '-' {
			p.args = append(p.args, arg)
			continue
		}

		trimmed := strings.TrimPrefix(strings.TrimPrefix(arg, "-"), "-")
		name, value, hasValue := strings.Cut(trimmed, "=")
		if name == "help" || name == "h" {
			return ErrHelp
		}
		f, ok := p.lookup[name]
		if !ok {
			return fmt.Errorf("unknown flag: %s", arg)
		}

		if f.isBool {
			*f.boolVal = true
			if hasValue {
				b, err := strconv.ParseBool(value)
				if err != nil {
					return fmt.Errorf("invalid boolean value %q for flag %s", value, name)
				}
				*f.boolVal = b
			}
			continue
		}

		if !hasValue {
			if i+1 >= len(argv) {
				return fmt.Errorf("flag needs a value: %s", arg)
			}
			i++
			value = argv[i]
		}
		*f.strVal = value
	}
	return nil
}

// Usage writes a help message generated from the flag definitions.
func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags] %s\n\nFlags:\n", p.name, p.positionals)
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	for _, f := range p.flags {
		names := "    --" + f.name
		if f.short != "" {
			names = "-" + f.short + ", --" + f.name
		}
		usage := f.usage
		if !f.isBool {
			names += " <value>"
			if f.def != "" {
				usage += fmt.Sprintf(" (default %q)", f.def)
			}
		}
		fmt.Fprintf(tw, "  %s\t%s\n", names, usage)
	}
	fmt.Fprintf(tw, "  -h, --help\tshow this help\n")
	tw.Flush()
}

func main() {
	p := NewParser("greet", "<name>...")
	verbose := p.Bool("verbose", "v", "print extra output")
	greeting := p.String("greeting", "g", "Hello", "greeting to use")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, ErrHelp) {
			p.Usage(os.Stdout)
			return
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		p.Usage(os.Stderr)
		os.Exit(2)
	}

	if len(p.Args()) == 0 {
		fmt.Fprintln(os.Stderr, "error: at least one name is required")
		p.Usage(os.Stderr)
		os.Exit(2)
	}

	for _, name := range p.Args() {
		fmt.Printf("%s, %s!\n", *greeting, name)
	}
	if *verbose {
		fmt.Printf("greeted %d name(s)\n", len(p.Args()))
	}
}
```

