- **Value syntax:** both `--greeting Hi` and `--greeting=Hi` work, and booleans accept an explicit `--verbose=false`.
- **Positionals:** flags and positional arguments can be interleaved, and everything after `--` is positional.
- **Dashes:** one or two dashes are treated the same, so `-verbose` and `--v` also match.
- **Short flags:** combined short flags such as `-vg Hi` are not supported.
- **Negative numbers:** a positional such as `-5` is read as an unknown flag unless it comes after `--`.
- **Types:** values are strings only; convert with `strconv` after parsing, or add an `Int` method following the `String` pattern.

If the goal is just to avoid dependencies rather than to write the parser yourself, the standard library's `flag` package covers the same features.

```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly pending: Array<() => Promise<void>> = [];
  private readonly idleWaiters: Array<() => void> = [];
  private running = 0;

  constructor(
    private readonly concurrency: number,
    private readonly maxRetries = 3,
  ) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError('concurrency must be a positive integer');
    }
  }

  /** Enqueue a job. Resolves with its result, or rejects with its last error once retries run out. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.runWithRetries(job));
        } catch (err) {
          reject(err);
        }
      });
      this.next();
    });
  }

  /** Resolves once nothing is running and nothing is waiting. */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  get size(): number {
    return this.pending.length + this.running;
  }

  private isIdle(): boolean {
    return this.running === 0 && this.pending.length === 0;
  }

  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    let lastError: unknown;
    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      try {
        return await job();
      } catch (err) {
        lastError = err;
      }
    }
    throw lastError;
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const task = this.pending.shift()!;
      this.running++;
      void task().finally(() => {
        this.running--;
        this.next();
        if (this.isIdle()) {
          for (const resolve of this.idleWaiters.splice(0)) resolve();
        }
      });
    }
  }
}
